// buildWorkspaceTaskCandidates merges member-repo task candidates by intent
// signature, keeping tasks shared by ≥2 repos. Evidence (procedures, facts,
// commands) is unioned and a per-repo breakdown is attached; the candidate is
// workspace-scoped.
func buildWorkspaceTaskCandidates(byRepo map[string][]taskCandidate, repoOrder []string, memberCount int, workspace string) []taskCandidate {
	type agg struct {
		base      taskCandidate
		repos     map[string]bool
		support   int
		reinf     reinforcementCounts
		cmds      map[string]bool
		procKeys  map[string]taskProcedure
		facts     map[string]bool
		intents   map[string]bool
		breakdown map[string]*patternRepoStat
	}
	aggs := map[string]*agg{}
	for _, repoKey := range repoOrder {
		for _, t := range byRepo[repoKey] {
			a := aggs[t.IntentSignature]
			if a == nil {
				a = &agg{base: t, repos: map[string]bool{}, cmds: map[string]bool{}, procKeys: map[string]taskProcedure{}, facts: map[string]bool{}, intents: map[string]bool{}, breakdown: map[string]*patternRepoStat{}}
				aggs[t.IntentSignature] = a
			}
	return counts, err
}

func buildWorkspacePatternCorpusLocked(env EntireEnv, manifest workspaceManifest, now time.Time) (workspaceCorpusCounts, error) {
	var counts workspaceCorpusCounts
	wsBrainDir, err := workspaceDir(env, manifest.Name)
	if err != nil {
		return counts, err
	}
	if err := recoverPatternCorpusPublicationLocked(wsBrainDir); err != nil {
		return counts, err
	}
	path, cleanup, err := preparePatternCorpusStaging(wsBrainDir)
	if err != nil {
		return counts, err
	}
	defer cleanup()
	db, err := sql.Open(sqliteDriverName, path)
	if err != nil {
		return counts, err
	}
	defer db.Close()
	for _, p := range []string{"PRAGMA busy_timeout=5000", "PRAGMA foreign_keys=ON"} {
		if _, err := db.Exec(p); err != nil {
			return counts, err
		}
	}
	for _, stmt := range patternCorpusSchema {
		if _, err := db.Exec(stmt); err != nil {
			return counts, err
		}
	}

	repos := append([]workspaceRepo(nil), manifest.Repos...)
	sort.Slice(repos, func(i, j int) bool { return repos[i].RepoKey < repos[j].RepoKey })
	counts.Members = len(repos)

	aggs := map[wsPatternKey]*wsAgg{}
	for _, repo := range repos {
		memberBrainDir, err := brainDirForKey(env, repo.RepoKey)
		if err != nil {
			counts.Warnings = append(counts.Warnings, repo.RepoKey+": "+err.Error())
			continue
		}
		mdb, err := openPatternCorpusReadDB(memberBrainDir)
		if err != nil {
			if errors.Is(err, os.ErrNotExist) {
				// A genuinely absent member corpus degrades gracefully (refresh that repo).
				counts.Warnings = append(counts.Warnings, repo.RepoKey+": no corpus (run `entire brain refresh` there)")
				continue
			}
			return counts, err
		}
		counts.WithCorpus++
		if err := collectMemberPatterns(mdb.DB, repo.RepoKey, aggs); err != nil {
			counts.Warnings = append(counts.Warnings, repo.RepoKey+": "+err.Error())
		}
		mdb.Close()
	}

	tx, err := db.Begin()
	if err != nil {
		return counts, err
	}
	// Rebuildable: clear all prior workspace corpus content, including the
	// verifier-cache tables — they have no FK cascade, so stale verdicts must not
	// survive a rebuild and join onto a newly-rebuilt pattern row sharing the same
	// stable id (which could even suppress it as 'rejected').
	// themes has no FK to episodes (not cascaded) and is never populated at
	// workspace scope, so clear it too — a stray theme row must not persist
	// across rebuilds, be fetchable via `workspace get theme:…`, or skew run counts.
	// EXCEPTION: agent-verified workspace families (`family:%` deep_dossiers) are
	// NOT pattern rows (loadAcceptedWorkspaceFamilies reads them directly, never via
	// a pattern-id join), so the stale-join hazard above does not apply. They are an
	// expensive agent result keyed by their own member-evidence fingerprint, so a
	// deterministic rebuild preserves them; `workspace patterns verify` invalidates
	// and re-proposes them when that content fingerprint changes.
	for _, stmt := range []string{`DELETE FROM patterns`, `DELETE FROM episodes`, `DELETE FROM workspace_pattern_repos`, `DELETE FROM dossiers`, `DELETE FROM deep_dossiers WHERE pattern_id NOT LIKE 'family:%'`, `DELETE FROM themes`} {
		if _, err := tx.Exec(stmt); err != nil {
			tx.Rollback()
			return counts, err
		}
	}
	ts := now.UTC().Format(time.RFC3339)
	}
	query := strings.TrimSpace(primary.QualifiedName)
	if query == "" {
		query = strings.TrimSpace(primary.Name)
	}
	if query == "" {
		return nil
	}
	candidateLimit := brainBriefExpandedCandidateLimit(limit, 3)
	// Exclusion guard: tombstoned sessions stay out of the focused
	// history context. The serving boundary loaded it fail-closed before
	// assembling the brief.
	var fGuardPred func(historyRecord) bool
	if !fGuard.empty() {
		fGuardPred = func(r historyRecord) bool { return !fGuard.blocksRecord(r) }
	}
	// rankFreshHistory keeps the FTS/fused arm on the on-disk long-term index
	// and fuses the short-term overlay in memory (Bugbot PR #77: passing a
	// merged index here rebuilt or misresolved the BM25 store).
	scored := rankFreshHistory(fresh, "history", query, candidateLimit, fGuardPred, func(longTerm historyIndex) ([]scoredHistoryRecord, bool) {
		return rankHistoryFused(brainDir, longTerm, "history", query, candidateLimit, defaultEmbedder())
	})
	records := make([]historyRecord, 0, len(scored))
	for _, item := range scored {
		if fGuardPred != nil && !fGuardPred(item.Record) {
			continue
		}
		records = append(records, item.Record)
	}
	// A command that merely searched for a symbol is weaker evidence than the
	// decision, patch, or documentation it was searching for. Keep the retriever
	// order within each evidence tier, but prevent shell-observation records from
	// displacing actual contract/rationale records in the compact packet.
	sort.SliceStable(records, func(i, j int) bool {
		return brainBriefFocusedHistoryEvidenceQuality(records[i]) >
			brainBriefFocusedHistoryEvidenceQuality(records[j])
	})
	matches := make([]brainTextMatch, 0, min(limit, len(records)))
	for _, record := range records {
		matches = append(matches, brainBriefHistoryRecordTextMatch(brainDir, record, query))
		if len(matches) >= limit {
			break
		}
	}
	return matches
}

func brainBriefFocusedHistoryEvidenceQuality(record historyRecord) int {
	summary := strings.ToLower(strings.TrimSpace(record.Summary))
	score := 0
	switch record.Kind {
	case "decision", "architecture", "learning", "code_fact":
		score += 30
	case "validation":
		score += 10
	}
	if strings.HasPrefix(summary, "apply_patch") ||
		strings.HasPrefix(summary, "edit ") ||
		strings.HasPrefix(summary, "write ") {
		score += 20
	}
	if strings.HasPrefix(summary, "bash ") ||
		strings.HasPrefix(summary, "exec_command ") ||
		strings.HasPrefix(summary, "grep ") ||
		strings.HasPrefix(summary, "rg ") {
		score -= 40
	}
	return score
}

func brainBriefHistoryRecordTextMatch(_ string, record historyRecord, _ string) brainTextMatch {
	return historyRecordTextMatch(record)
}

func historyInspectKinds(kind string) map[string]struct{} {
	switch kind {
	case "decisions":
		return map[string]struct{}{"decision": {}}
	case "requests":
		return map[string]struct{}{"request": {}}
	case conversationKind:
		// Experimental conversation exchanges; reached only through the explicit
		// conversation retrieval source, never the general history sweep.
		return map[string]struct{}{conversationKind: {}}
	case "validation":
		return map[string]struct{}{"validation": {}}
	case "tool-paths":
		return map[string]struct{}{"tool_call": {}}
	case "architecture":
		return map[string]struct{}{"architecture": {}, "code_fact": {}, "decision": {}, "learning": {}}
	case "history", "sessions":
		return nil
	default:
		return nil
	}
}

func agentSurfaceTarget(opts Options, args []string) string {
	if len(args) == 1 {
		return args[0]
	}
	if opts.Env.RepoRoot != "" {
		return opts.Env.RepoRoot
	}
	return "."
}

func truncateString(value string, max int) string {
	if max <= 0 {
		return ""
	}
	if len(value) <= max {
		return value
	}
	// Cut on a rune boundary so we never split a multi-byte UTF-8 rune in
	// real (non-ASCII) transcripts, which would emit invalid UTF-8.
	limit := max
	suffix := ""
	if max > 3 {
		limit = max - 3
		suffix = "..."
	for path, score := range counts {
		if brainBriefLikelyTestFile(path) {
			testCounts[path] = score
		} else {
			editCounts[path] = score
		}
	}
	editFiles := rankedBrainBriefLikelyFiles(editCounts, 8)
	testFiles := rankedBrainBriefLikelyFiles(testCounts, 6)
	all := append([]string{}, editFiles...)
	for _, file := range testFiles {
		if len(all) >= 12 {
			break
		}
		all = append(all, file)
	}
	return editFiles, testFiles, all
}

func brainBriefCurrentCodeFileCounts(repoRoot, task string) map[string]int {
	if brainBriefPreviousResponseTask(task) {
		return brainBriefCurrentCodeFileCountsByScore(repoRoot, brainBriefPreviousResponseFileScore)
	}
	if !brainBriefProviderMetadataTask(task) {
		return nil
	}
	return brainBriefCurrentCodeFileCountsByScore(repoRoot, brainBriefProviderMetadataFileScore)
}

func brainBriefCurrentCodeFileCountsByScore(repoRoot string, scoreFile func(string, string) int) map[string]int {
	counts := map[string]int{}
	walked := 0
	_ = filepath.WalkDir(repoRoot, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if path == repoRoot {
			return nil
		}
		rel, relErr := filepath.Rel(repoRoot, path)
		if relErr != nil {
			return nil
		}
		rel = filepath.ToSlash(rel)
		if d.IsDir() {
			if brainBriefSkipSourceDir(rel) {
				return filepath.SkipDir
			}
			return nil
		}
		if walked >= 2500 || !brainBriefSourceFile(rel) {
			return nil
		}
		walked++
		info, statErr := d.Info()
		if statErr != nil || info.Size() > brainInspectHistoryMaxBytes {
			return nil
		}
		data, readErr := brainBriefReadRepoFile(repoRoot, rel)
		if readErr != nil {
			return nil
		}
		score := scoreFile(rel, string(data))
		if score >= 90 {
			counts[rel] = score
		}
		return nil
	})
	return counts
}

